<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {AlertTriangle,FileText,Info} from 'lucide-vue-next'
import {api} from '../lib/api'
import {bytesLabel,friendlyError} from '../lib/format'
import type {SavedLayout} from '../lib/bundleSettings'
import type {Job} from '../lib/types'
import OutputOptions from './OutputOptions.vue'
const props=defineProps<{matterId:string;disabled:boolean;inputsDirty:boolean;refreshKey:number;job:Job|null;initialRecovery?:boolean;returnToIndex?:boolean}>()
const emit=defineEmits<{close:[];modified:[];build:[];cancel:[];navigate:[name:string];dirtyChanged:[value:boolean]}>()
type Document={id:string;title:string;revision:number;page_count:number;bytes:number}
type Row={id:string;title:string;revision:number;source_start:number;source_end:number;total_pages:number;printed_start:string;printed_end:string}
type Volume={number:number;page_count:number;index_pages:number;cover_pages:number;estimated_bytes:number;combined_start_page:number;combined_end_page:number;rows:Row[]}
type Planning={generated?:{build_id:string;files:Array<{name:string;bytes:number}>};input_snapshot:string;documents:Document[];plan_error?:string;plan?:{volumes:Volume[];combined_pages:number;source_pages:number;generated_pages:number;included_documents:number};measured_exception?:{job_id:string;input_snapshot:string;size_exceptions:Array<{filename:string;bytes:number;limit_bytes:number;document_ids:string[]}>}}
const settings=ref<SavedLayout|null>(null),baseline=ref(''),data=ref<Planning|null>(null),error=ref(''),loading=ref(false),saving=ref(false),reviewed=ref(''),mode=ref<'plan'|'recovery'>(props.initialRecovery?'recovery':'plan'),choice=ref<''|'limit'|'split'>(''),selectedId=ref(''),boundary=ref(''),authorized=ref(false),proposedLimit=ref<number|null>(null),options=ref(false),optionsDirty=ref(false),status=ref('')
const closeDialog=ref<HTMLDialogElement|null>(null),heading=ref<HTMLElement|null>(null),optionsRef=ref<InstanceType<typeof OutputOptions>|null>(null)
let alive=true,sequence=0,pendingAction:()=>void=()=>emit('close'),focusBefore:HTMLElement|null=null,processingChanged=false
const dirty=computed(()=>!!settings.value&&JSON.stringify(settings.value)!==baseline.value)
const payload=computed(()=>settings.value?{max_pages_per_volume:settings.value.max_pages_per_volume,keep_groups_intact:settings.value.keep_groups_intact,output_marks:settings.value.output_marks,expected_snapshot:settings.value.input_snapshot}:null)
const fingerprint=computed(()=>JSON.stringify(payload.value))
const currentPreview=computed(()=>!!data.value&&reviewed.value===fingerprint.value)
const plan=computed(()=>data.value?.plan)
const selected=computed(()=>data.value?.documents.find(d=>d.id===selectedId.value)||data.value?.documents[0])
const limit=computed(()=>settings.value?.output_marks.volume_max_bytes||null)
const measured=computed(()=>data.value?.measured_exception?.size_exceptions.find(e=>!selected.value||e.document_ids.includes(selected.value.id)))
const affectedBytes=computed(()=>measured.value?.bytes??selected.value?.bytes??0)
const activeLimit=computed(()=>measured.value?.limit_bytes??limit.value)
const oversized=computed(()=>!!activeLimit.value&&affectedBytes.value>activeLimit.value)
const busy=computed(()=>props.disabled||saving.value||loading.value)
watch([dirty,optionsDirty],()=>emit('dirtyChanged',dirty.value||optionsDirty.value))
watch(fingerprint,()=>{status.value=''})
function body(){return JSON.parse(JSON.stringify(payload.value))}
async function preview(){if(!payload.value||saving.value)return false;const call=++sequence,key=fingerprint.value;reviewed.value='';loading.value=true;error.value='';try{const result=await api<Planning>(`/matters/${props.matterId}/volume-planning`,'POST',body());if(!alive||call!==sequence||key!==fingerprint.value)return false;data.value=result;reviewed.value=key;if(!selectedId.value)selectedId.value=result.measured_exception?.size_exceptions[0]?.document_ids[0]||result.documents.find(d=>limit.value&&d.bytes>limit.value)?.id||result.documents[0]?.id||'';return !result.plan_error}catch(e){if(alive&&call===sequence)error.value=friendlyError(e);return false}finally{if(alive&&call===sequence)loading.value=false}}
async function load(){const call=++sequence;loading.value=true;error.value='';try{const result=await api<SavedLayout>(`/matters/${props.matterId}/bundle-settings`);if(!alive||call!==sequence)return;settings.value=result;baseline.value=JSON.stringify(result);await nextTick();loading.value=false;await preview()}catch(e){if(alive)error.value=friendlyError(e)}finally{if(alive)loading.value=false}}
async function saveDraft(){if(optionsDirty.value)return await optionsRef.value!.saveDraft();if(!settings.value||busy.value||props.inputsDirty)return false;if(!dirty.value)return true;if(!currentPreview.value||data.value?.plan_error){error.value='Preview the current choices successfully before applying.';return false}const key=fingerprint.value;saving.value=true;error.value='';try{const result=await api<SavedLayout>(`/matters/${props.matterId}/bundle-settings`,'PUT',body());if(!alive)return false;if(key!==fingerprint.value)throw Error('Settings changed during save; reload and review.');settings.value=result;baseline.value=JSON.stringify(result);reviewed.value='';status.value='Choices saved. Rebuild to measure and validate generated files.';emit('modified');void nextTick(()=>heading.value?.focus());return true}catch(e){if(alive)error.value=friendlyError(e);return false}finally{if(alive)saving.value=false}}
async function applyBuild(){if(await saveDraft()){closeDialog.value?.close();emit('build');await preview()}}
function discard(){if(baseline.value)settings.value=JSON.parse(baseline.value);choice.value='';authorized.value=false;optionsRef.value?.discard();reviewed.value=''}
function leave(action:()=>void){if(saving.value||props.disabled)return;pendingAction=action;if(dirty.value||optionsDirty.value){focusBefore=document.activeElement as HTMLElement;closeDialog.value?.showModal()}else action()}
function keepEditing(){closeDialog.value?.close();void nextTick(()=>focusBefore?.focus())}
async function saveLeave(){if(await saveDraft()){closeDialog.value?.close();pendingAction()}}
function back(){if(mode.value==='recovery'){choice.value='';mode.value='plan';void nextTick(()=>heading.value?.focus())}else leave(()=>emit('close'))}
function recover(){mode.value='recovery';void nextTick(()=>heading.value?.focus())}
function choose(which:'limit'|'split'){choice.value=which;proposedLimit.value=limit.value;boundary.value=(selected.value&&settings.value?.output_marks.volume_splits?.[selected.value.id]?.after_pages.join(', '))||'';authorized.value=false;void nextTick(()=>document.querySelector<HTMLElement>('.recovery-editor input')?.focus())}
async function previewChoice(){if(!settings.value)return;if(choice.value==='limit'){if(proposedLimit.value!==null&&(!Number.isInteger(proposedLimit.value)||proposedLimit.value<1)){error.value='Enter a positive whole-byte limit, or clear it for no optional volume limit.';return}settings.value.output_marks.volume_max_bytes=proposedLimit.value||null}else if(choice.value==='split'&&selected.value){const cuts=boundary.value.split(',').map(v=>Number(v.trim()));if(!authorized.value||cuts.some((v,i)=>!Number.isInteger(v)||v<1||v>=selected.value!.page_count||(i>0&&v<=cuts[i-1]))){error.value='Authorize an increasing list of internal source-page boundaries.';return}settings.value.output_marks.volume_splits={...settings.value.output_marks.volume_splits,[selected.value.id]:{revision:selected.value.revision,after_pages:cuts}}}choice.value='';await nextTick();await preview()}
function openOptions(){if(dirty.value){error.value='Preview and save the volume draft before reviewing processing options.';return}processingChanged=false;options.value=true;focusBefore=document.activeElement as HTMLElement}
async function closeOptions(){options.value=false;if(processingChanged){await load();emit('modified');status.value='Processing choices saved. Rebuild to measure the result.'}void nextTick(()=>focusBefore?.focus())}
function keydown(e:KeyboardEvent){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();e.stopPropagation();void saveDraft()}else if(e.key==='Escape'&&!options.value&&!closeDialog.value?.open){e.preventDefault();e.stopPropagation();back()}}
watch(()=>props.refreshKey,()=>{if(!dirty.value&&!saving.value&&!options.value)void load()})
onMounted(()=>{void load();heading.value?.focus()})
onBeforeUnmount(()=>{alive=false;sequence++;closeDialog.value?.close();emit('dirtyChanged',false)})
defineExpose({saveDraft,discard})
</script>
<template>
<section class="volume-workspace" :data-mode="mode" aria-label="Volume planning workspace" @keydown="keydown">
 <header class="volume-heading"><div><h1 ref="heading" tabindex="-1">{{mode==='plan'?'Plan volumes':'Review a size-limit exception'}}</h1><p>{{mode==='plan'?`Current inputs ${settings?.input_snapshot.slice(0,8)||'…'} · Review page counts and estimated file sizes independently.`:'Alternative document selection · Preview choices before changing the current volume plan.'}}</p></div><div class="volume-actions"><template v-if="mode==='plan'"><button class="membership-button secondary" @click="leave(()=>emit('navigate','Presets'))">Presets</button><button class="membership-button primary" @click="leave(()=>emit('navigate','Preflight'))">Run preflight</button></template><button v-else class="membership-button secondary" @click="back">Back to volumes</button></div></header>
 <nav v-if="mode==='plan'" class="volume-tabs" aria-label="Bundle preparation"><button class="membership-button quiet" @click="leave(()=>emit('navigate','map'))">Index &amp; page map</button><button class="membership-button quiet" @click="leave(()=>emit('navigate','Bookmarks'))">Bookmarks</button><button class="membership-button primary" aria-current="page">Volume planning</button><span/><button class="membership-button secondary" @click="openOptions">Output policy</button><button class="membership-button secondary" @click="recover">Size recovery</button></nav>
 <div v-if="error" role="alert" class="volume-alert">{{error}} <button class="text-tool" @click="preview">Retry preview</button><button class="text-tool" @click="leave(()=>{discard();void load()})">Reload saved settings</button></div>
 <p v-if="loading" role="status">Calculating current inputs…</p><p v-if="inputsDirty">Save pending bundle settings before applying this draft.</p>
 <template v-if="settings">
 <div v-if="mode==='plan'" class="volume-columns">
  <fieldset class="volume-policy" :disabled="busy"><h2>Workflow settings</h2><label>Target maximum per volume<input aria-label="Maximum pages per volume" type="number" min="2" max="2000" v-model.number="settings.max_pages_per_volume"/></label><p class="volume-policy-note">Includes cover and index pages.<br/>This is a workflow limit, not a<br/>universal court requirement.</p><label class="volume-check"><input type="checkbox" checked disabled/>Keep documents together</label><label class="volume-check"><input type="checkbox" checked disabled/>Include volume front matter</label><label>Printed numbering<select v-model="settings.output_marks.numbering_restart"><option value="volume">Restart in each volume</option><option value="continuous">Continue across volumes</option><option value="section">Restart in each Part</option></select></label><p class="volume-mini">Printed numbering is separate from combined PDF positions. Start: {{settings.output_marks.numbering_start}} · {{settings.output_marks.numbering_style}}</p><label>Volume PDF limit (optional, bytes)<input aria-label="Volume PDF limit in bytes" type="number" min="1" :value="settings.output_marks.volume_max_bytes??''" placeholder="No optional volume byte limit" @input="settings.output_marks.volume_max_bytes=($event.target as HTMLInputElement).value?Number(($event.target as HTMLInputElement).value):null"/></label><details class="volume-extra"><summary>Groups and front matter</summary><label class="volume-check"><input type="checkbox" v-model="settings.keep_groups_intact"/>Keep document groups together</label><label>Front matter<select v-model="settings.output_marks.front_matter"><option value="index_only">Index in each volume</option><option value="cover_index">Cover and index in each volume</option></select></label><p>Only explicitly reviewed split exceptions break a document.</p></details></fieldset>
  <section class="volume-results"><h2>{{plan?`${plan.volumes.length} volumes · ${plan.combined_pages} physical pages`:'Volume plan unavailable'}}</h2><p class="volume-summary">{{plan?`${plan.source_pages} included source pages + ${plan.generated_pages} generated pages`:'Include documents to calculate a plan.'}} <span v-if="!currentPreview">· Preview needed</span></p><p v-if="data?.plan_error" role="alert" class="volume-alert">{{data.plan_error}} <button class="text-tool" @click="recover">Review recovery choices</button></p><p v-if="data&&!data.documents.length">No included documents. Return to Build bundle to review membership.</p>
   <article v-for="v in plan?.volumes" :key="v.number" class="planned-volume"><div class="planned-volume-top"><h3>Volume {{v.number}}</h3><span :title="`${v.estimated_bytes.toLocaleString()} estimated bytes`">{{bytesLabel(v.estimated_bytes)}} estimated{{limit?` / ${bytesLabel(limit)}`:''}}</span><strong>{{v.page_count}} / {{settings.max_pages_per_volume}} pages</strong></div><progress :value="v.page_count" :max="settings.max_pages_per_volume"/><div class="volume-range"><span>{{v.rows.reduce((n,r)=>n+r.total_pages,0)}} source + {{v.page_count-v.rows.reduce((n,r)=>n+r.total_pages,0)}} generated</span><span>Printed {{v.rows[0]?.printed_start}}–{{v.rows[v.rows.length-1]?.printed_end}} · Combined {{v.combined_start_page}}–{{v.combined_end_page}}</span></div><p v-if="data?.generated&&!dirty" class="volume-mini">Build {{data.generated.build_id.slice(0,8)}} · {{bytesLabel(data.generated.files.find(f=>f.name===`volume-${String(v.number).padStart(2,'0')}.pdf`)?.bytes||0)}} measured generated bytes</p><details><summary>Included documents and revisions</summary><p v-for="r in v.rows" :key="`${r.id}:${r.source_start}`">{{r.title}} · r{{r.revision}} · source {{r.source_start+1}}–{{r.source_end}}</p></details></article>
   <div class="volume-placement"><strong><Info :size="16"/>{{Object.keys(settings.output_marks.volume_splits||{}).length?'Reviewed split exceptions are active':'Documents stay together'}}</strong><p>Estimates use source-file proportions plus generated-page overhead; processing and shared images can change actual bytes.</p><button class="text-tool" @click="recover">Adjust placement</button></div>
  </section>
 </div>
 <template v-else>
  <div class="size-warning"><strong><AlertTriangle :size="16"/>{{oversized?(measured?'Selected output exceeds the workflow limit':'Source size exceeds the selected allowance'):activeLimit?'Review the selected size policy':'No optional volume byte limit selected'}}</strong><p>{{measured?`${measured.filename}: ${bytesLabel(measured.bytes)} measured in failed build ${data?.measured_exception?.job_id.slice(0,8)}`:selected?`${selected.title}: ${bytesLabel(selected.bytes)} measured source file; generated volume size remains an estimate`:'No included document is available.'}}{{activeLimit?` / ${activeLimit.toLocaleString()} bytes per volume PDF.`:'.'}} No document is split without explicit review.</p></div>
  <div class="recovery-columns"><section class="affected-document"><h2>{{measured?'Affected artifact / source':'Affected document'}}</h2><div class="affected-name"><FileText :size="28"/><select aria-label="Affected document" v-model="selectedId" @change="choice=''"><option v-for="d in data?.documents" :key="d.id" :value="d.id">{{d.title}}</option></select></div><p>{{selected?.page_count??0}} source pages · working revision {{selected?.revision??'—'}}</p><strong class="affected-size" :title="`${affectedBytes.toLocaleString()} bytes`">{{bytesLabel(affectedBytes)}}</strong><p>{{measured?'Measured failed volume':'Measured source; output estimate only'}} / {{activeLimit?bytesLabel(activeLimit)+' selected limit':'no selected limit'}}</p><progress :value="activeLimit?Math.min(100,activeLimit/Math.max(affectedBytes,1)*100):0" max="100"/><p>{{oversized?`${bytesLabel(affectedBytes-activeLimit!)} above the limit`:'Generated bytes must be checked after rebuilding'}}</p><hr/><strong>Keep documents together</strong><p>This preference stays on except for reviewed boundaries. None of these choices changes the imported original.</p></section>
   <section class="recovery-paths"><h2>Choose a recovery path</h2><article class="recommended"><div><h3>Review optimization</h3><p>Review supported image changes; no target size is guaranteed.</p></div><button class="membership-button primary" :disabled="busy" @click="openOptions">Review policy</button></article><article><div><h3>Raise the output policy’s volume limit</h3><p>Choose a file allowance for individual volume PDFs.</p></div><button class="membership-button secondary" :disabled="busy" @click="choose('limit')">Choose limit</button></article><article><div><h3>Split at a chosen boundary</h3><p>Allow a volume break inside this document after reviewing the split.</p></div><button class="membership-button secondary" :disabled="busy||!selected||selected.page_count<2" @click="choose('split')">Choose split</button></article></section></div>
  <p class="size-scope">This limit applies to individual volume PDFs. Combined-PDF, ZIP and profile limits are separate. Estimates do not establish successful size reduction.</p>
  <section v-if="choice" class="recovery-editor"><h2>{{choice==='limit'?'Preview a policy limit':'Review internal source-page boundaries'}}</h2><label v-if="choice==='limit'">Maximum bytes per volume PDF<input aria-label="Proposed volume byte limit" type="number" min="1" :value="proposedLimit??''" @input="proposedLimit=($event.target as HTMLInputElement).value?Number(($event.target as HTMLInputElement).value):null"/></label><template v-else><p>{{selected?.title}} · revision {{selected?.revision}} · {{selected?.page_count}} pages. A new output volume starts after each chosen source page, with its own front matter.</p><label>Split after source pages (comma separated)<input v-model="boundary" aria-label="Split after source pages" placeholder="Enter reviewed source page numbers"/></label><label class="volume-check"><input type="checkbox" v-model="authorized"/>I authorize these output-volume boundaries inside this document.</label><button v-if="selected&&settings.output_marks.volume_splits?.[selected.id]" class="text-tool" @click="delete settings.output_marks.volume_splits![selected.id];choice='';preview()">Remove this document’s split exception</button></template><button class="membership-button secondary" @click="choice=''">Cancel choice</button><button class="membership-button primary" @click="previewChoice">Preview choice</button></section>
  <section v-if="dirty&&currentPreview" class="recovery-preview"><h2>Proposed volume plan</h2><p v-if="data?.plan_error" role="alert">{{data.plan_error}}</p><p v-for="v in plan?.volumes" :key="v.number">Volume {{v.number}} · {{v.page_count}} physical pages · combined {{v.combined_start_page}}–{{v.combined_end_page}} · {{bytesLabel(v.estimated_bytes)}} estimated</p><p>New limit: {{limit?limit.toLocaleString()+' bytes per volume':'no optional volume byte limit'}}. Applying requires a rebuild and measured validation.</p></section>
 </template>
 </template>
 <footer class="volume-footer"><span role="status">{{saving?'Saving choices…':status|| (dirty?'Unapplied choices':currentPreview?'Current preview':'Preview needed')}}</span><button class="membership-button secondary" :disabled="busy" @click="leave(()=>emit('close'))">{{returnToIndex?'Back to index':'Back to build'}}</button><button class="membership-button secondary" :disabled="busy||!settings" @click="preview">Preview changes</button><button v-if="dirty" class="membership-button secondary" :disabled="busy||!currentPreview||!!data?.plan_error||inputsDirty" @click="saveDraft">Save choices</button><button class="membership-button primary" :disabled="busy||!currentPreview||!!data?.plan_error||!data?.documents.length||inputsDirty" @click="applyBuild">{{dirty?'Apply & rebuild':'Rebuild & validate'}}</button></footer>
 <div v-if="job?.kind==='build'" class="volume-job" role="status">Build {{job.id.slice(0,8)}} · {{job.status}} · {{job.error||job.message}}<button v-if="['running','queued'].includes(job.status)" class="text-tool" @click="emit('cancel')">Cancel build</button><button v-else class="text-tool" @click="leave(()=>emit('close'))">Review build and files</button></div>
 <dialog ref="closeDialog" class="volume-dirty-dialog" aria-label="Unsaved volume choices" @cancel.prevent="keepEditing"><h2>Save unapplied volume choices?</h2><p>Preview the draft before saving. Discard restores saved settings.</p><button class="membership-button secondary" @click="keepEditing">Keep editing</button><button class="membership-button secondary" @click="discard();closeDialog?.close();pendingAction()">Discard changes</button><button class="membership-button primary" :disabled="!currentPreview||!!data?.plan_error||busy" @click="saveLeave">Save changes</button></dialog>
 <OutputOptions v-if="options" ref="optionsRef" :matter-id="matterId" :disabled="disabled" :inputs-dirty="dirty||inputsDirty" @dirty-changed="optionsDirty=$event" @modified="processingChanged=true" @close="closeOptions"/>
</section>
</template>
